mod support;

use std::sync::Arc;
use maho_agent::harness::context::BACKGROUND_CONTEXT;
use maho_agent::harness::env::nodejs::NodeExecutionEnv;
use maho_agent::harness::session::jsonl::legacy_v3::LegacyV3Source;
use maho_agent::harness::types::FileSystem;
use serde_json::{json, Value};

const NOW: i64 = 1_700_000_000_000;
fn root(label: &str) -> String { let p=std::env::temp_dir().join(format!("maho-jsonl-stream-{label}-{}-{}",std::process::id(),support::unique_suffix()));std::fs::create_dir_all(&p).expect("root");p.to_string_lossy().into_owned() }
fn iso() -> String { "2023-11-14T22:13:20.000Z".into() }
fn message(id:&str,parent:Option<&str>,content:&str)->Value {json!({"type":"message","id":id,"parentId":parent,"timestamp":iso(),"message":{"role":"user","content":content,"timestamp":NOW}})}
async fn source(root:&str,records:&[Value],suffix:&str)->(Arc<dyn FileSystem>,String,LegacyV3Source){let f:Arc<dyn FileSystem>=Arc::new(NodeExecutionEnv::new(root.to_owned()));let path:String="legacy.jsonl".to_owned();let mut lines=vec![json!({"type":"session","version":3,"id":"legacy","timestamp":iso(),"cwd":"/workspace"})];lines.extend_from_slice(records);let content=lines.iter().map(Value::to_string).collect::<Vec<_>>().join("\n")+"\n"+suffix;f.write_file(&path,content.as_bytes(),&BACKGROUND_CONTEXT).await.expect("write");let s=LegacyV3Source::read(f.clone(),&path,&BACKGROUND_CONTEXT).await.expect("read");(f,path,s)}
#[tokio::test] async fn selected_compaction_materializes_branch_tail(){let r=root("selected");let (_f,_p,s)=source(&r,&[message("before",None,"before"),json!({"type":"session_info","id":"boundary","parentId":"before","timestamp":iso()}),message("kept",Some("boundary"),"Unicode é漢字"),message("other",Some("before"),"other"),json!({"type":"compaction","id":"selected","parentId":"kept","timestamp":iso(),"summary":"selected","firstKeptEntryId":"boundary","tokensBefore":20,"fromHook":true,"details":{"a":2}})],"").await;let id=s.entry_structures().last().unwrap().id.clone();let writes=s.writes(BACKGROUND_CONTEXT.clone(),Some(Arc::new(move|x|x==id))).await.expect("writes");assert_eq!(writes.len(),2);std::fs::remove_dir_all(r).expect("cleanup")}
#[tokio::test] async fn selected_compactions_reuse_cached_branch_message(){let r=root("cached");let (_f,_p,s)=source(&r,&[message("root",None,"root"),message("left",Some("root"),"left"),json!({"type":"compaction","id":"lc","parentId":"left","timestamp":iso(),"summary":"left","firstKeptEntryId":"root","tokensBefore":10}),message("right",Some("root"),"right"),json!({"type":"compaction","id":"rc","parentId":"right","timestamp":iso(),"summary":"right","firstKeptEntryId":"root","tokensBefore":20})],"").await;let ids=s.entry_structures();let selected=Arc::new(move|id:&str|id==ids[2].id||id==ids[4].id);let writes=s.writes(BACKGROUND_CONTEXT.clone(),Some(selected)).await.expect("writes");assert_eq!(writes.len(),3);std::fs::remove_dir_all(r).expect("cleanup")}
#[tokio::test] async fn ignores_torn_tail_and_captures_complete_records(){let r=root("torn");let (f,p,s)=source(&r,&[message("a",None,"a")],&message("torn",Some("a"),"torn").to_string()).await;f.append_file(&p,format!("\n{}\n",message("later",Some("torn"),"later")).as_bytes(),&BACKGROUND_CONTEXT).await.expect("append");let writes=s.writes(BACKGROUND_CONTEXT.clone(),None).await.expect("writes");assert_eq!(writes.len(),2);assert_eq!(s.next_seq,3);std::fs::remove_dir_all(r).expect("cleanup")}
